from datetime import UTC, datetime, timedelta; from unittest.mock import patch; import jwt; from src.config import settings; from src.identity import create_access_token, decode_access_token
def test_create_access_token_with_custom_expiry():
    data = {'sub': 'user123'}; expires_delta = timedelta(hours=2); token = create_access_token(data, expires_delta); decoded = jwt.decode(token, settings.secret_key, algorithms=[settings.jwt_algorithm]); assert decoded['sub'] == 'user123'; assert 'exp' in decoded; _m1_before = datetime.now(UTC); _m1_data = {'sub': 'user456'}; _m1_token = create_access_token(_m1_data); _m1_after = datetime.now(UTC); _m1_options = {'verify_exp': False}; _m1_decoded = jwt.decode(_m1_token, settings.secret_key, algorithms=[settings.jwt_algorithm], options=_m1_options); assert _m1_decoded['sub'] == 'user456'; assert 'exp' in _m1_decoded; _m1_exp_datetime = datetime.fromtimestamp(_m1_decoded['exp'], tz=UTC); _m1_expected_min = _m1_before + timedelta(minutes=settings.access_token_expire_minutes) - timedelta(seconds=1); _m1_expected_max = _m1_after + timedelta(minutes=settings.access_token_expire_minutes) + timedelta(seconds=1); assert _m1_expected_min <= _m1_exp_datetime <= _m1_expected_max; _m2_data = {'sub': 'user789', 'role': 'admin'}; _m2_token = create_access_token(_m2_data); _m2_payload = decode_access_token(_m2_token); assert _m2_payload is not None; assert _m2_payload['sub'] == 'user789'; assert _m2_payload['role'] == 'admin'; _m3_data = {'sub': 'expired_user'}; _m3_expires_delta = timedelta(seconds=-1); _m3_token = create_access_token(_m3_data, _m3_expires_delta)
    with patch('src.identity.extension.security.logger.debug') as _m3_mock_debug: _m3_payload = decode_access_token(_m3_token)
    assert _m3_payload is None; _m3_mock_debug.assert_called_once_with('JWT token expired'); _m4_data = {'sub': 'user999'}; _m4_token = jwt.encode(_m4_data, 'wrong-secret', algorithm=settings.jwt_algorithm)
    with patch('src.identity.extension.security.logger.warning') as _m4_mock_warning: _m4_payload = decode_access_token(_m4_token)
    assert _m4_payload is None; _m4_mock_warning.assert_called_once(); _m4_first_arg = _m4_mock_warning.call_args[0][0]; assert _m4_first_arg == 'JWT decode failed'; 'AC8.2.3'; 'AC8.2.3'; _m5_token = 'not.a.valid.jwt.token'
    with patch('src.identity.extension.security.logger.warning') as _m5_mock_warning: _m5_payload = decode_access_token(_m5_token)
    assert _m5_payload is None; _m5_mock_warning.assert_called_once(); assert decode_access_token('') is None; assert decode_access_token(None) is None
